const fs=require('node:fs');const path=require('node:path');
const files=[];for(const d of ['src','test'])for(const f of fs.readdirSync(d,{recursive:true}))if(f.endsWith('.js'))files.push(path.join(d,f));
const changed=[];
for(const f of files){const s=fs.readFileSync(f,'utf8');const t=s.replace(/\bretryPolicy\b/g,'backoffPolicy').replace(/\bmaxAttempts: 3\b/g,'maxAttempts: 5');if(t!==s){fs.writeFileSync(f,t);changed.push(f);}}
const left=(await $`grep -rnE "retryPolicy|maxAttempts: 3" src test`).stdout;
const t=await $`node --test 2>&1`;
return {changed,left,exit:t.exitCode,out:t.stdout.slice(-3000)};

